export const courses=[{id:'bandon',name:'Bandon Dunes',region:'Oregon coast',target:245,media:true},{id:'pinehurst',name:'Pinehurst No. 2',region:'North Carolina',target:250,media:true},{id:'pebble',name:'Pebble Beach Golf Links',region:'California coast',target:260,media:true},{id:'sawgrass',name:'TPC Sawgrass · Stadium Course',region:'Ponte Vedra Beach, Florida',target:255,media:true}];
const cache=new Map();
export async function loadCourse(id){if(!courses.some(c=>c.id===id))throw new Error('Choose a course from the demo library');if(!cache.has(id))cache.set(id,fetch(`data/${id}.json`).then(r=>{if(!r.ok)throw new Error('Course data could not load');return r.json();}).catch(e=>{cache.delete(id);throw e;}));return cache.get(id);}
export function routePosition(route,fraction){if(!route?.length)return null;const scale=Math.cos(route[0][0]*Math.PI/180),lengths=route.slice(1).map((p,i)=>Math.hypot(p[0]-route[i][0],(p[1]-route[i][1])*scale));let left=lengths.reduce((n,l)=>n+l,0)*Math.max(0,Math.min(1,fraction));for(let i=0;i<lengths.length;i++){if(left<=lengths[i]||i===lengths.length-1){const t=lengths[i]?left/lengths[i]:0;return [route[i][0]+(route[i+1][0]-route[i][0])*t,route[i][1]+(route[i+1][1]-route[i][1])*t];}left-=lengths[i];}return route[0];}
